DROP TABLE IF EXISTS `building`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `building` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `building_name` varchar(50) NOT NULL COMMENT '楼栋名称',
  `building_number` varchar(20) NOT NULL COMMENT '楼栋编号',
  `floor_count` int NOT NULL COMMENT '楼层数',
  `room_count` int NOT NULL COMMENT '房间数',
  `manager_id` bigint DEFAULT NULL COMMENT '宿管员ID',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `building_number` (`building_number`)
) ENGINE=InnoDB AUTO_INCREMENT=101 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='宿舍楼表';
